import type { ReactNode } from 'react';

/** Уровень относительно нормы: цвет рамки карточки (для карточек долей предела). */
export type Level = 'negligible' | 'within' | 'exceeds';

/** Класс словесной оценки по дозе самого нагруженного года: c1 — не выше 10 мкЗв, c2 — до 1 мЗв, c3 — выше 1 мЗв. */
export type DoseClass = 'c1' | 'c2' | 'c3';

/** Итоговые показатели сценария, как их считает калькулятор (#FR-81 V02, D-022). */
export interface RiskTotals {
  /** Главное число R: номинальный риск смерти от последствий облучения за весь срок (доля; 0,05 Зв⁻¹ · доза техногенных нуклидов); `null` — только природные нуклиды. */
  riskNominal: number | null;
  /** Доза самого нагруженного года по техногенным нуклидам, Зв; `null` — техногенных нет. */
  doseMaxYearTech: number | null;
  /** Номер самого нагруженного года (с 1); возраст в начале года — только в режиме «с a до b». */
  doseMaxYearIndex: number | null;
  doseMaxYearAge: number | null;
  /** Класс словесной оценки; `null` — техногенных нуклидов нет. */
  doseClass: DoseClass | null;
  /** Номинальный риск от самого нагруженного года (доля). */
  riskMaxYear: number | null;
  /** Доза всех нуклидов за весь срок, Зв. */
  doseSvTotal: number | null;
}

/** Описание колонки таблицы. */
export interface Column<R = any> {
  /** Заголовок колонки. */
  h: string;
  /** Значение ячейки для строки. */
  f: (row: R) => ReactNode;
  /** Класс ячейки (например `num` — число, выравнивание вправо) или функция от строки. */
  c?: string | ((row: R) => string);
  /** Ячейка содержит готовую разметку: `f` возвращает HTML-строку. */
  html?: boolean;
}
